import styled from "styled-components";
import { FiSearch, FiBell, FiPlus } from "react-icons/fi";

function Home() {
  return (
    <Wrap>
      {/* TOP BAR */}
      <Top>
        <Logo>READLY</Logo>

        <Icons>
          <FiPlus />
          <FiSearch />
          <FiBell />
        </Icons>
      </Top>

      {/* BIG CARD */}
      <HeroCard />

      {/* LIST */}
      <SectionTitle>텍스트 삽입 부분입니다</SectionTitle>

      <CardList>
        <Card />
        <Card />
        <Card />
      </CardList>
    </Wrap>
  );
}

export default Home;

/* ===== styled ===== */

const Wrap = styled.div`
  padding: 15px;
  background: #F6FBF2;
`;

const Top = styled.div`
  display: flex;
  justify-content: space-between;
  align-items: center;
`;

const Logo = styled.div`
  font-weight: 800;
  font-size: 20px;
`;

const Icons = styled.div`
  display: flex;
  gap: 10px;
  font-size: 18px;
`;

const HeroCard = styled.div`
  margin-top: 15px;
  height: 220px;
  border-radius: 20px;
  background: #8BC34A;
`;

const SectionTitle = styled.h3`
  margin-top: 20px;
  font-size: 14px;
`;

const CardList = styled.div`
  margin-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 10px;
`;

const Card = styled.div`
  height: 70px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 2px 6px rgba(0,0,0,0.05);
`;
